'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );


// MAIN //

/**
* Computes the epsilon insensitive loss.
*
* @param {number} e - insensitivity parameter
* @param {number} y - true target value
* @param {number} p - predicted value
* @returns {number} epsilon insensitive loss
*
* @example
* var v = epsilonInsensitive( 5.0, 10.2, 0.782 );
* // returns 4.418
*
* @example
* var v = epsilonInsensitive( 2.0, 8.0, 0.202 );
* // returns 5.798
*
* @example
* var v = epsilonInsensitive( 1.0, 23.2, -0.999 );
* // returns 23.199
*
* @example
* var v = epsilonInsensitive( 11.0, -12.2, 0.234 );
* // returns ~1.434
*
* @example
* var v = epsilonInsensitive( 2.0, -21.0, 0.2 );
* // returns 19.2
*
* @example
* var v = epsilonInsensitive( 9.0, 4.0, -0.9 );
* // returns 0.0
*/
function epsilonInsensitive( e, y, p ) {
	if ( isnan( e ) || isnan( y ) || isnan( p ) ) {
		return NaN;
	}
	if ( ( y-p ) > e ) {
		return ( y-p ) - e;
	}
	if ( ( p-y ) > e ) {
		return ( p-y ) - e;
	}
	return 0.0;
}


// EXPORTS //

module.exports = epsilonInsensitive;
